def solve(data):
    nums = data['nums']
    if not nums:
        return None

    candidate = nums[0]
    count = 1

    for num in nums[1:]:
        if num == candidate:
            count += 1
        else:
            count -= 1

        if count == 0:
            candidate = num
            count = 1

    # Check if the candidate is the majority element
    if nums.count(candidate) > len(nums) // 2:
        return candidate
    else:
        return None

