    s = data['s']
    if not s:
        return 1

    count = 0
    for i in range(1, len(s) + 1):
        num_str = s[:i]
        if int(num_str) >= 1 and int(num_str) <= 26:
            count += solve({'s': s[i:]})

    return count

def solve(data):
    s = data['s']
    n = len(s)

    # Edge case: empty string
    if not s:
        return 1

    # Edge case: single digit string
    if n == 1 and '0' <= s[0] <= '9':
        return 1

    # Edge case: leading zero
    if s[0] == '0':
        return 0

    # Initialize DP array
    dp = [0] * (n + 1)
    dp[0] = 1

    # Fill DP array
    for i in range(1, n + 1):
        for j in range(i):
            if '0' <= s[j] <= '9' and int(s[j:i]) <= 26:
                dp[i] += dp[j]

    return dp[n]

