def solve(data: dict) -> int:
    nums = data['nums']

    if not nums:
        return 0

    # Initialize the result to zero
    total_sum = 0

    # Calculate the sum of Hamming distances for each pair of numbers
    for i in range(len(nums)):
        for j in range(i + 1, len(nums)):
            total_sum += bin(nums[i] ^ nums[j]).count('1')

    return total_sum

