def solve(data):
    rows = data['rows']
    s = data['s']

    if rows == 1 or len(s) <= rows:
        return s

    zigzag = [''] * rows
    direction = 1  # 1 for down, -1 for up

    for i, char in enumerate(s):
        zigzag[i % rows] += char

        if i % rows == 0 or i % rows == rows - 1:
            direction *= -1

    return ''.join(zigzag)

def solve(data):
    path = data['path']
    components = path.split('/')
    result = []

    for component in components:
        if component == '.':
            continue
        elif component == '..':
            if result:
                result.pop()
        else:
            result.append(component)

    return '/'.join(result)

