def solve(data):
    gas = data['gas']
    cost = data['cost']

    # Edge cases
    if not gas or not cost or len(gas) != len(cost):
        return -1

    # Brute-force approach: try all starting points
    n = len(gas)
    for start in range(n):
        tank = 0
        for i in range(n):
            tank += gas[(start + i) % n]
            tank -= cost[(start + i) % n]
            if tank < 0:
                break
        else:
            return start

    return -1

